def solve_with_pysat(n, fixed):
    from pysat.solvers import Glucose3
    solver = Glucose3()

    # Variables: x[i][j] is true if mark is at (i, j)
    # i is row, j is column
    def var(i, j):
        return i * n + j + 1

    # Each column has one mark
    for j in range(n):
        solver.add_clause([var(i, j) for i in range(n)])
        for i1 in range(n):
            for i2 in range(i1 + 1, n):
                solver.add_clause([-var(i1, j), -var(i2, j)])

    # Each row has one mark
    for i in range(n):
        solver.add_clause([var(i, j) for j in range(n)])
        for j1 in range(n):
            for j2 in range(j1 + 1, n):
                solver.add_clause([-var(i, j1), -var(i, j2)])

    # Costas condition: all (r2-r1, c2-c1) are distinct
    # For all c1 < c2, r1, r2:
    # If (r1, c1) and (r2, c2) are marks, then (r2-r1, c2-c1) is a vector.
    # For all c1 < c2, c3 < c4, if c2-c1 == c4-c3 and (c1, c2) != (c3, c4),
    # then r2-r1 != r4-r3.

    for dc in range(1, n):
        for dr in range(-(n-1), n):
            # For a fixed (dr, dc), there can be at most one pair of marks
            # with (r2-r1, c2-c1) = (dr, dc)
            # This means for all c1, c2 such that c2-c1 = dc:
            # Not (mark at (r1, c1) and mark at (r1+dr, c2))

            pairs = []
            for c1 in range(n - dc):
                c2 = c1 + dc
                for r1 in range(n):
                    r2 = r1 + dr
                    if 0 <= r2 < n:
                        pairs.append((r1, c1, r2, c2))

            # For each (dr, dc), at most one pair
            for i in range(len(pairs)):
                for j in range(i + 1, len(pairs)):
                    # If both pairs are true, it's a contradiction
                    solver.add_clause([-var(pairs[i][0], pairs[i][1]), -var(pairs[i][2], pairs[i][3]),
                                       -var(pairs[j][0], pairs[j][1]), -var(pairs[j][2], pairs[j][3])])

    # Fixed values
    for col, row in fixed.items():
        solver.add_clause([var(row, col)])

    if solver.solve():
        model = solver.get_model()
        res = [0] * n
        for i in range(n):
            for j in range(n):
                if model[var(i, j) - 1] > 0:
                    res[j] = i
        return res
    else:
        return None

